"""Every country as it stood on 6 November 2024, the morning after the
US presidential election was called.

Leaders are the person running the government that day. People who take
over later (Trump on 20 January 2025, Merz in May 2025, ...) are listed in
`others` and arrive through events.
"""
from .model import Country, Leader, Advisor, Look as K


def L(name, sub, traits, look, title="", desc="", key=""):
    return Leader(name, sub, traits, look, title, desc, key)


def A(name, role, traits, look, cost=150, slot="political_advisor"):
    return Advisor(name, role, traits, look, cost, slot)


def pp(d=0, c=0, f=0, n=0):
    total = d + c + f + n
    assert total == 100, (d, c, f, n, total)
    return dict(democratic=d, communism=c, fascism=f, neutrality=n)


def P(d=None, c=None, f=None, n=None):
    out = {}
    for ide, val in (("democratic", d), ("communism", c), ("fascism", f), ("neutrality", n)):
        if val:
            out[ide] = val
    return out


